def link_videos_to_sports(apps, schema_editor):
    """EmotionVideo를 적절한 Sports에 자동 연결"""
    EmotionVideo = apps.get_model('emodia', 'EmotionVideo')
    Sports = apps.get_model('emodia', 'Sports')

    # Sports 매핑 (exercise_type 또는 body_part 기반)
    sports_mapping = {
        '목·어깨 스트레칭': ['목', '어깨', '목어깨'],
        '전신 스트레칭': ['전신', '등', '골반'],
        '요가': ['요가'],
        '필라테스': ['필라테스'],
        '코어 운동': ['코어'],
    }

    for video in EmotionVideo.objects.all():
        # 이미 연결되어 있으면 스킵
        if video.sports:
            continue

        # exercise_type 우선 확인
        exercise_type = video.exercise_type
        if exercise_type:
            # '요가'나 '필라테스'가 exercise_type에 포함되어 있으면
            if '요가' in exercise_type:
                sports = Sports.objects.filter(name='요가').first()
                if sports:
                    video.sports = sports
                    video.save()
                    continue
            elif '필라테스' in exercise_type:
                sports = Sports.objects.filter(name='필라테스').first()
                if sports:
                    video.sports = sports
                    video.save()
                    continue
            elif '운동' in exercise_type:
                sports = Sports.objects.filter(name='코어 운동').first()
                if sports:
                    video.sports = sports
                    video.save()
                    continue

        # body_part로 매핑
        body_part = video.body_part
        for sports_name, body_parts in sports_mapping.items():
            if body_part in body_parts:
                sports = Sports.objects.filter(name=sports_name).first()
                if sports:
                    video.sports = sports
                    video.save()
                    break

        # 매핑되지 않은 경우 기본값: 전신 스트레칭
        if not video.sports:
            sports = Sports.objects.filter(name='전신 스트레칭').first()
            if sports:
                video.sports = sports
                video.save()


def reverse_link(apps, schema_editor):
    """롤백 시 sports 연결 해제"""
    EmotionVideo = apps.get_model('emodia', 'EmotionVideo')
    EmotionVideo.objects.all().update(sports=None)


